import express, { Express } from "express";
import { CatalogueService } from "../application/catalogue-service";
import { OrderService } from "../application/order-service";
import { InMemoryOrderRepository, InMemoryProductRepository } from "./in-memory-repositories";
import { OrderController } from "./order-controller";

export function createServer(): Express {
  const products = new InMemoryProductRepository();
  const orders = new InMemoryOrderRepository();
  const app = express();
  app.use(express.json());
  app.use(new OrderController(new CatalogueService(products), new OrderService(orders, products)).routes());
  return app;
}

if (require.main === module) {
  const port = Number(process.env.PORT ?? 3000);
  createServer().listen(port, () => console.log(`Order fulfilment API listening on port ${port}`));
}

